<script setup lang="ts">
import { reactive,ref } from 'vue'
import { api,errorText } from '../api'
import { useRequestKey } from '../composables'
import type { Definition } from '../types'
const props=defineProps<{targetId:string;definition?:Definition}>(),emit=defineEmits<{done:[];cancel:[];refresh:[]}>(),key=useRequestKey()
const d=props.definition,form=reactive({method:d?.method||'GET',intervalSeconds:d?.intervalSeconds||60,timeoutMs:d?.timeoutMs||3000,statuses:d?.expectedStatuses.join(', ')||'200',failThreshold:d?.failThreshold||3,recoverThreshold:d?.recoverThreshold||2,reason:''})
const busy=ref(false),error=ref('')
async function save(){busy.value=true;error.value='';const config={method:form.method,intervalSeconds:form.intervalSeconds,timeoutMs:form.timeoutMs,expectedStatuses:form.statuses.split(',').map(s=>Number(s.trim())),failThreshold:form.failThreshold,recoverThreshold:form.recoverThreshold};try{if(d)await api(`/targets/${props.targetId}/checks/${d.id}`,{method:'PUT',body:{configVersion:d.configVersion,config,reason:form.reason}});else await api(`/targets/${props.targetId}/checks`,{method:'POST',body:config,key:key.forBody(config)});key.clear();emit('done')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><form class="inline-form" @submit.prevent="save"><h3>{{ definition?'编辑检查配置':'新增健康检查' }}</h3><p class="muted">新检查保存后处于未启用状态，需手动启用。</p><div v-if="error" class="error-message" role="alert">{{ error }}<button v-if="definition" type="button" class="text-button" @click="emit('refresh')">放弃编辑并刷新</button></div><div class="form-grid three"><label>请求方法<select v-model="form.method"><option>GET</option><option>HEAD</option></select></label><label>检查间隔（秒）<input v-model.number="form.intervalSeconds" required type="number" min="60" max="86400"></label><label>请求超时（毫秒）<input v-model.number="form.timeoutMs" required type="number" min="100" max="10000"></label><label>预期 HTTP 状态码<input v-model="form.statuses" required pattern="[0-9 ,]+" placeholder="200, 204"><small>多个状态码用英文逗号分隔。</small></label><label>连续失败阈值<input v-model.number="form.failThreshold" required type="number" min="1" max="20"></label><label>连续恢复阈值<input v-model.number="form.recoverThreshold" required type="number" min="1" max="20"></label><label v-if="definition" class="span-all">变更理由<textarea v-model="form.reason" required maxlength="500" rows="2"></textarea></label></div><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="emit('cancel')">取消</button><button class="btn primary" :disabled="busy">{{ busy?'保存中…':'保存检查' }}</button></div></form></template>
